# 205 - registrazione e lista dei brani eseguiti: solo i brani fatti partire dalla scaletta

import sys
import types

_VER = 4
_SORGENTE = '# -*- coding: utf-8 -*-\n"""Registrazione della diretta e Lista Brani Eseguiti: decide il PLAY dell\'utente.\n\nRichiesta dell\'utente (10-10-2026): "la registrazione non deve partire da una\ninterpretazione ma dal mio play, che sia nella libreria o dal comando", e nella\nlista SIAE "solo i brani cantati".\n\nPrima:\n  * un controllo ogni 0,4 s (_bridge_writer) faceva partire/fermare la registrazione\n    guardando "sta suonando qualcosa che non sembra sottofondo";\n  * il sottofondo con "solo audio" spento chiamava load_file come un brano normale e\n    load_file metteva in pausa... il sottofondo stesso (pause_for_user_song): da li\'\n    "e\' sottofondo?" rispondeva NO e si registrava anche il sottofondo;\n  * la lista la scrivevano solo alcuni punti (libreria, YouTube, tasto play): la\n    playlist e l\'avvio automatico non lasciavano traccia.\n\nOra:\n  * BRANO DELL\'UTENTE = caricato da chiunque tranne il gestore del sottofondo\n    (si guarda chi chiama load_file/play, non lo stato del programma);\n  * registrazione: START al play di un brano dell\'utente, STOP a stop/fade/fine\n    brano; se parte un brano nuovo mentre registra: STOP subito e START dopo 2,5 s\n    (il telefono legge l\'ultimo comando una volta al secondo: due comandi vicini\n    si perderebbero); il controllo periodico scrive solo il file di stato;\n  * lista: ogni brano dell\'utente, con l\'ora del play; se il vecchio codice lo ha\n    gia\' scritto (titoli YouTube) non si duplica.\n"""\nimport os\nimport sys\nimport time\nimport threading\n\n_VER = 4\n_SISTEMA = [None]          # il sistema, per sapere se il brano in corso conta\n_RITARDO_START = 2.5\n\n\ndef _da_sottofondo(prof=2):\n    """True se a chiamare e\' il gestore del sottofondo."""\n    try:\n        f = sys._getframe(prof)\n        for _ in range(4):\n            if f is None:\n                break\n            chi = f.f_locals.get(\'self\')\n            if chi is not None and type(chi).__name__ == \'SottoFondoManager\':\n                return True\n            f = f.f_back\n    except Exception:\n        pass\n    return False\n\n\ndef _titolo(self):\n    t = (getattr(self, \'_bridge_song\', \'\') or \'\').strip()\n    if t:\n        return t\n    try:\n        p = getattr(self, \'_original_file\', None) or getattr(self, \'current_file\', \'\') or \'\'\n        return os.path.splitext(os.path.basename(str(p)))[0]\n    except Exception:\n        return \'\'\n\n\ndef _scrivi_lista(titolo, quando):\n    try:\n        try:\n            from . import history as H\n        except Exception:\n            from moduli import history as H\n        fp = H.init_session_file()\n        riga = "%s\\t - No auth.\\t\\t\\t%s\\n" % (time.strftime(\'%H:%M:%S\', time.localtime(quando)), titolo)\n        with open(fp, \'a\', encoding=\'utf-8\') as f:\n            f.write(riga)\n        print("📝 History (play): %s" % titolo)\n    except Exception as e:\n        print("[BRANI] lista: %s" % e)\n\n\ndef _lista_cantanti_accesa():\n    try:\n        try:\n            from .database import Database\n        except Exception:\n            from moduli.database import Database\n        return str(Database.get_config(\'lista_cantanti\', \'0\')).strip() == \'1\'\n    except Exception:\n        return False\n\n\ndef _scrivi_lista_cantanti(cantante, titolo, quando):\n    """Lista SECONDARIA (solo dove \'lista_cantanti\' = 1): ora, chi canta, brano.\n    Stessa sessione del file SIAE, nella sottocartella \'Con cantanti\'."""\n    try:\n        try:\n            from . import history as H\n        except Exception:\n            from moduli import history as H\n        d = H.get_history_folder() / \'Con cantanti\'\n        d.mkdir(parents=True, exist_ok=True)\n        fp = d / H.get_session_filename()\n        nuovo = not fp.exists()\n        with open(fp, \'a\', encoding=\'utf-8\') as f:\n            if nuovo:\n                f.write(\'ORA\\tCANTANTE\\tBRANO\\n\')\n            f.write(\'%s\\t%s\\t%s\\n\' % (time.strftime(\'%H:%M:%S\', time.localtime(quando)),\n                                      (cantante or \'---\').strip(), titolo))\n    except Exception as e:\n        print("[BRANI] lista cantanti: %s" % e)\n\n\ndef _aggancia_history():\n    try:\n        try:\n            from . import history as H\n        except Exception:\n            from moduli import history as H\n    except Exception:\n        return\n    if getattr(H, \'_bu_ver\', None) == _VER:\n        return\n    o = getattr(H, \'_bu_o_log\', None) or H.log_brano\n    H._bu_o_log = o\n\n    def log_brano(titolo_brano, cantante=""):\n        # i punti vecchi del programma scrivono da soli: se il brano NON e\' in scaletta non conta\n        s = _SISTEMA[0]\n        if s is not None and not getattr(s, \'_bu_conta\', True):\n            return False\n        H._bu_ultimo = time.time()\n        return o(titolo_brano, cantante)\n\n    H.log_brano = log_brano\n    H._bu_ultimo = 0.0\n    H._bu_ver = _VER\n\n\ndef _rec_cmd_post(self, action, motivo=\'\'):\n    """Comando al telefono (rec_cmd.php). Con START manda anche il NOME di chi canta (riga\n    della scaletta): il telefono lo lega al video e la conversione lo scrive sul video."""\n    brano = getattr(self, \'_bridge_song\', \'\') or \'\'\n    cantante = (getattr(self, \'_bu_rec_cantante\', \'\') or \'\').strip() if action == \'start\' else \'\'\n\n    def _do():\n        import urllib.request\n        import urllib.parse\n        t0 = time.time()\n        try:\n            rid = os.environ.get("KARADOM_REC_ID") or getattr(self, "_rec_id_software", None) or "4738261-01"\n            par = {"id_software": rid, "action": action, "key": "recCmd_9Xk2pQ"}\n            if cantante and cantante != \'---\':\n                par["cantante"] = cantante\n            url = "https://karadomlive.karadom.it/rec_cmd.php?" + urllib.parse.urlencode(par)\n            urllib.request.urlopen(url, timeout=5).read()\n            esito = \'ok %.1fs\' % (time.time() - t0)\n        except Exception as e:\n            esito = \'ERRORE %s: %s (riprovo)\' % (type(e).__name__, e)\n            if getattr(self, \'_rec_live_state\', None) == (action == \'start\'):\n                self._rec_live_state = None\n        riga = \'%s %s | %s | %s | %s | %s\' % (time.strftime(\'%H:%M:%S\', time.localtime(t0)), action.upper(),\n                                            motivo, cantante or \'-\', brano, esito)\n        try:\n            print(\'[DIRETTA] \' + riga)\n        except Exception:\n            pass\n        try:\n            d = os.path.join(os.environ.get("LOCALAPPDATA") or os.path.expanduser("~"), "KaraDom")\n            os.makedirs(d, exist_ok=True)\n            p = os.path.join(d, "diretta.log")\n            if os.path.exists(p) and os.path.getsize(p) > 1024 * 1024:\n                os.replace(p, p + ".vecchio")\n            with open(p, "a", encoding="utf-8") as f:\n                f.write(time.strftime(\'%d/%m \') + riga + "\\n")\n        except Exception:\n            pass\n    threading.Thread(target=_do, daemon=True).start()\n\n\ndef _norma(p):\n    p = str(p or \'\').strip()\n    if not p:\n        return \'\'\n    if \'://\' in p:\n        return p\n    return os.path.normcase(os.path.normpath(p))\n\n\ndef _riga_in_scaletta(lib, path, brano=\'\'):\n    """Il cantante della riga di scaletta che ha QUESTO brano, oppure None se non e\' in scaletta."""\n    cerca = _norma(path)\n    if not cerca:\n        return None\n    for r in getattr(lib, \'righe\', None) or ():\n        try:\n            rp = r.get(\'path\') or \'\'\n            rb = r[\'brano\'].get() if r.get(\'brano\') is not None else \'\'\n            if _norma(rp) == cerca or (not rp and rb and rb.strip() == str(path).strip()):\n                c = (r[\'cantante\'].get() or \'\').strip()\n                return c if c else \'---\'\n        except Exception:\n            continue\n    return None\n\n\ndef installa_libreria(L):\n    """play_brano della libreria dice al sistema CHI canta il brano che sta per partire."""\n    if L is None or getattr(L, \'_bu_ver\', None) == _VER or not hasattr(L, \'play_brano\'):\n        return\n    o = getattr(L, \'_bu_o_play_brano\', None) or L.play_brano\n    L._bu_o_play_brano = o\n\n    def play_brano(self, path, entry_ton=None, cantante="", brano="", tonalita=None, *a, **k):\n        # CONTA (lista + registrazione) solo un brano che e\' in SCALETTA: si cerca la riga col\n        # suo percorso; il cantante e\' quello della riga\n        try:\n            riga = _riga_in_scaletta(self, path, brano)\n            if getattr(self, \'system\', None) is not None:\n                self.system._bu_scaletta_prossimo = riga is not None\n                self.system._bu_cantante_prossimo = (riga or \'\').upper()\n        except Exception:\n            pass\n        return o(self, path, entry_ton, cantante, brano, tonalita, *a, **k)\n\n    L.play_brano = play_brano\n    L._bu_ver = _VER\n\n\ndef installa(S, SM=None, L=None):\n    """S = KaraokeMonitorSystem, SM = SottoFondoManager, L = LibreriaSlider (facoltativi)."""\n    _aggancia_history()\n    installa_libreria(L)\n    if S is not None and getattr(S, \'_bu_ver\', None) != _VER:\n        o = {}\n        for n in (\'load_file\', \'_bridge_writer\', \'_rec_live\'):\n            if hasattr(S, n):\n                o[n] = getattr(S, \'_bu_o_\' + n, None) or getattr(S, n)\n                setattr(S, \'_bu_o_\' + n, o[n])\n        # play SENZA la vecchia decisione sulla registrazione: sotto la 188 c\'e\' il play\n        # originale (_dl188_o_play); nel sorgente c\'e\' _play_brano\n        if getattr(S, \'_bu_o_play\', None) is None:\n            if getattr(S, \'_dl188_o_play\', None) is not None:\n                S._bu_o_play = S._dl188_o_play\n            elif hasattr(S, \'_play_brano\'):\n                S._bu_o_play = lambda self, *a, **k: self._play_brano(*a, **k)\n            else:\n                S._bu_o_play = S.play\n        o[\'play\'] = S._bu_o_play\n\n        def _rec_live(self, on, motivo=\'\'):\n            # i comandi del vecchio controllo periodico (\'suona\'/\'fermo\'/\'sottofondo\') non contano piu\'\n            if motivo in (\'suona\', \'fermo\', \'sottofondo\'):\n                return None\n            return o[\'_rec_live\'](self, on, motivo)\n\n        def load_file(self, *a, **k):\n            sotto = _da_sottofondo()\n            self._bu_carica_sottofondo = sotto\n            try:\n                return o[\'load_file\'](self, *a, **k)\n            finally:\n                self._bu_carica_sottofondo = False\n                _SISTEMA[0] = self\n                self._bu_utente = not sotto\n                # conta solo se a farlo partire e\' stata una riga della SCALETTA\n                self._bu_conta = (not sotto) and bool(getattr(self, \'_bu_scaletta_prossimo\', False))\n                self._bu_scaletta_prossimo = False\n                if not sotto:\n                    self._bu_gen = getattr(self, \'_bu_gen\', 0) + 1\n                    self._bu_cantante = getattr(self, \'_bu_cantante_prossimo\', \'\') or \'\'\n                    self._bu_cantante_prossimo = \'\'\n\n        def play(self, *a, **k):\n            sotto = _da_sottofondo() or not getattr(self, \'_bu_utente\', True)\n            conta = (not sotto) and getattr(self, \'_bu_conta\', False)\n            r = o[\'play\'](self, *a, **k)\n            try:\n                self._rec_live_fading = False\n                if not conta:\n                    self._rec_live(False, \'sottofondo al play\' if sotto else \'fuori scaletta\')\n                    return r\n                gen = getattr(self, \'_bu_gen\', 0)\n                adesso = time.time()\n                self._bu_rec_cantante = getattr(self, \'_bu_cantante\', \'\') or \'\'\n                # --- registrazione: dal play ---\n                if getattr(self, \'_rec_live_state\', None) is True:\n                    self._rec_live(False, \'brano nuovo\')\n\n                    def _poi(g=gen):\n                        if getattr(self, \'_bu_gen\', 0) == g and getattr(self, \'is_playing\', False) \\\n                                and getattr(self, \'_bu_conta\', False):\n                            self._rec_live(True, \'play\')\n                    threading.Timer(_RITARDO_START, _poi).start()\n                else:\n                    self._rec_live(True, \'play\')\n                # --- lista: se entro 3 s nessun altro l\'ha scritto, la scrivo io con l\'ora del play ---\n                if getattr(self, \'_bu_listato\', None) != gen:\n                    self._bu_listato = gen\n                    titolo = _titolo(self)\n                    if _lista_cantanti_accesa():\n                        _scrivi_lista_cantanti(getattr(self, \'_bu_cantante\', \'\'), titolo, adesso)\n\n                    def _lista(t0=adesso, tit=titolo):\n                        try:\n                            try:\n                                from . import history as H\n                            except Exception:\n                                from moduli import history as H\n                            if getattr(H, \'_bu_ultimo\', 0.0) >= t0 - 1.0:\n                                return\n                        except Exception:\n                            pass\n                        if tit:\n                            _scrivi_lista(tit, t0)\n                    threading.Timer(3.0, _lista).start()\n            except Exception as e:\n                print(\'[BRANI] play: %s\' % e)\n            return r\n\n        def _bridge_writer(self):\n            """Solo il file di stato per gli altri programmi: la registrazione la decide il play."""\n            import json\n            import tempfile\n            base = os.environ.get("LOCALAPPDATA") or tempfile.gettempdir()\n            d = os.path.join(base, "KaraDom")\n            try:\n                os.makedirs(d, exist_ok=True)\n            except Exception:\n                d = tempfile.gettempdir()\n            path = os.path.join(d, "studio_bridge.json")\n            while getattr(self, "_bridge_alive", True):\n                try:\n                    playing = bool(getattr(self, "is_playing", False)) and not bool(getattr(self, "is_paused", False))\n                    data = {"playing": playing, "song": getattr(self, "_bridge_song", ""), "ts": time.time()}\n                    tmp = path + ".tmp"\n                    with open(tmp, "w", encoding="utf-8") as f:\n                        json.dump(data, f)\n                    os.replace(tmp, path)\n                except Exception:\n                    pass\n                time.sleep(0.4)\n\n        if \'load_file\' in o:\n            S.load_file = load_file\n        if \'_rec_live\' in o:\n            S._rec_live = _rec_live\n        S._rec_cmd_post = _rec_cmd_post\n        S.play = play\n        if \'_bridge_writer\' in o:\n            S._bridge_writer = _bridge_writer\n        S._bu_ver = _VER\n\n    if SM is not None and getattr(SM, \'_bu_ver\', None) != _VER:\n        o_pausa = getattr(SM, \'_bu_o_pausa\', None) or SM.pause_for_user_song\n        SM._bu_o_pausa = o_pausa\n\n        def pause_for_user_song(self, *a, **k):\n            # il sottofondo che carica il SUO brano non deve mettersi in pausa da solo\n            if getattr(getattr(self, \'system\', None), \'_bu_carica_sottofondo\', False):\n                return None\n            return o_pausa(self, *a, **k)\n\n        SM.pause_for_user_song = pause_for_user_song\n        SM._bu_ver = _VER\n'


def _spenta():
    try:
        from moduli.database import Database
        return str(Database.get_config('patch_205', '1')).strip() in ('0', 'no', 'off')
    except Exception:
        return False


def _modulo():
    try:
        import importlib
        vero = importlib.import_module('moduli.brani_utente')
        if getattr(vero, '__file__', '') != '<patch205>' and hasattr(vero, 'installa'):
            return vero
    except Exception:
        pass
    m = sys.modules.get('moduli.brani_utente')
    if m is not None and getattr(m, '_ver205', None) == _VER:
        return m
    m = types.ModuleType('moduli.brani_utente')
    m.__file__ = '<patch205>'
    m.__package__ = 'moduli'
    exec(compile(_SORGENTE, 'brani_utente_205', 'exec'), m.__dict__)
    m._ver205 = _VER
    sys.modules['moduli.brani_utente'] = m
    try:
        import moduli
        moduli.brani_utente = m
    except Exception:
        pass
    return m


def apply():
    if _spenta():
        return False
    try:
        m = _modulo()
        import moduli.system as SYS
        try:
            import moduli.sottofondo as SF
            SM = getattr(SF, 'SottoFondoManager', None)
        except Exception as e:
            print('[BRANI205] sottofondo:', e)
            SM = None
        try:
            import moduli.libreria as LIB
            L = getattr(LIB, 'LibreriaSlider', None)
        except Exception as e:
            print('[BRANI205] libreria:', e)
            L = None
        m.installa(getattr(SYS, 'KaraokeMonitorSystem', None), SM, L)
        print('[BRANI205] registrazione e lista: dal play del brano, mai dal sottofondo')
    except Exception as e:
        print('[BRANI205] hook:', e)
    return True


def revert():
    pass


try:
    apply()
except Exception as _e:
    print('patch 205: %s' % _e)
